#!/usr/bin/env python3
"""my_gen_test.py (v-e3-rmbuild): Lemma V deletion + tight-clique tests for the cyclic address group generated by an
arbitrary h in GL(m,2), given by the images of the basis vectors (h e_1, ..., h e_m as ints).
Usage: my_gen_test.py m W cols dirs   e.g.  my_gen_test.py 4 4 2,4,1,8 all   (dirs: all | plain | e1xM | list:..)"""
import sys
sys.path.insert(0, __file__.rsplit("/", 1)[0])
from my_vtests import forms, max_clique

m, W = int(sys.argv[1]), int(sys.argv[2]); cols = [int(t) for t in sys.argv[3].split(",")]; dirs = sys.argv[4]
N = 1 << m


def lin(cols):
    img = []
    for x in range(N):
        y = 0
        for k in range(m):
            if x >> k & 1:
                y ^= cols[k]
        img.append(y)
    return img


g = lin(cols); assert len(set(g)) == N
H = [list(range(N))]
while True:
    nxt = [g[v] for v in H[-1]]
    if nxt == list(range(N)):
        break
    H.append(nxt)
n = len(H)
Hinv = []
for h in H:
    inv = [0] * N
    for x in range(N):
        inv[h[x]] = x
    Hinv.append(inv)
if dirs == "all":
    Z = list(range(1, N))
elif dirs == "plain":
    Z = [1 << j for j in range(m)] * W
elif dirs.startswith("list:"):
    Z = [int(t) for t in dirs[5:].split(",")]
else:
    Z = [1] * int(dirs.split("x")[1])
M = len(Z)
nfail = 0; tight = []
for bits, Q in forms(m):
    D = [(t, k) for t in range(M) for k in range(n) if Q[Hinv[k][Z[t]]]]
    nodd = sum(1 for k in range(n) if sum(Q[Hinv[k][1 << j]] for j in range(m)) & 1)
    sl = len(D) - W * nodd
    if sl < 0:
        nfail += 1
    elif sl == 0 and D:
        tight.append(D)
adj = {}
for D in tight:
    S = set(D)
    for v in D:
        adj.setdefault(v, set()).update(S - {v})
cl = max_clique(adj, list(adj)) if adj else []
print("m=%d h=%s (order %d) W=%d M=%d dirs=%s: deletion failures %d, tight forms %d, max clique %d, bound %d -> %s"
      % (m, cols, n, W, M, dirs if len(dirs) < 30 else dirs[:30] + "..", nfail, len(tight), len(cl), W * n,
         "EXCLUDED (deletion)" if nfail else ("EXCLUDED (clique)" if len(cl) > W * n else "not excluded")))
